// Campos base de CurricularSection (el resto van al satelite rt__<RT>__curricularsection, creado anidado)
const BASE_FIELDS = ['ownerActivityCode','recordType','sectionType','name','position','isSynchronizable','isVisible','isRequired','ref'];

export async function loadSyllabusSections(prisma, tenantId) {
  if (tenantId !== 'UPU') return { skipped: true, reason: `tenant ${tenantId} no UPU` };
  const institution = await prisma.institution.findFirst({ where: { code: 'UPU-MAIN' } });
  const actCache = {};
  async function actId(code){ if(!(code in actCache)){ const a=await prisma.activity.findFirst({where:{code}}); actCache[code]=a?a.id:null; } return actCache[code]; }
  let created=0, skipped=0;
  for (const s of SECTIONS) {
    const ownerId = await actId(s.ownerActivityCode);
    if (!ownerId) { skipped++; continue; }
    const existing = await prisma.curricularSection.findFirst({ where: { ownerId, recordType: s.recordType, name: s.name } });
    if (existing) { skipped++; continue; }
    // Campos del satelite (todo lo no-base)
    const sat = {};
    for (const k of Object.keys(s)) { if (!BASE_FIELDS.includes(k) && s[k] !== null && s[k] !== undefined) sat[k] = s[k]; }
    // Bibliography: crea/reusa BibliographyReference y linkea via libraryRefId (en el satelite)
    if (s.recordType === 'Bibliography' && s.ref) {
      let ref = await prisma.bibliographyReference.findFirst({ where: { title: s.ref.title, author: s.ref.author, institutionId: institution.id } });
      if (!ref) ref = await prisma.bibliographyReference.create({ data: { ...s.ref, institutionId: institution.id } });
      sat.libraryRefId = ref.id;
    }
    const rel = `rt__${s.recordType}__curricularsection`; // relacion 1:1 al satelite (mismo patron que rt__Plan__curriculum)
    await prisma.curricularSection.create({ data: {
      ownerType:'Activity', ownerId, recordType:s.recordType, sectionType:s.sectionType, name:s.name,
      position:s.position, isSynchronizable:s.isSynchronizable, isVisible:s.isVisible, isRequired:s.isRequired,
      [rel]: { create: sat },
    }});
    created++;
  }
  return { created, skipped, total: SECTIONS.length };
}